const headerAuth = $input.first().json.headers?.['x-webhook-secret'] || $input.first().json.headers?.authorization || '';
const body = $input.first().json.body || $input.first().json;
const secretKey = String(body.secret_key || headerAuth || '').replace('Bearer ', '').trim();

// SECURITY CHECK: Production Webhook Authentication
const EXPECTED_SECRET = 'ZERO_PROD_SECRET_8921_SECURE';
if (secretKey && secretKey !== EXPECTED_SECRET && secretKey !== 'Bearer ' + EXPECTED_SECRET) {
  throw new Error('401 Unauthorized: Invalid Webhook Secret Key. Access Denied.');
}

const symbol = String(body.symbol || body.ticker || 'MARKET').toUpperCase();
const action = String(body.action || body.side || 'TRADE').toUpperCase();
const broker = String(body.broker || body.exchange || 'Trading Bot').trim();
const tradeId = String(body.trade_id || body.order_id || Date.now());
const rawPnl = Number(body.pnl ?? body.profit ?? body.amount ?? 0);
const date = String(body.date || new Date().toISOString().slice(0, 10)).trim();
const month = date.slice(0, 7);
const notes = String(body.notes || `${symbol} ${action} trade via ${broker}`).trim();
const whatsappNumber = String(body.whatsapp_number || '1104381256');
const currency = String(body.currency || 'INR').toUpperCase();
const currencySymbol = currency === 'USD' ? '$' : (currency === 'EUR' ? '€' : '₹');

const isProfit = rawPnl >= 0;
const absAmount = Math.abs(rawPnl);
const type = isProfit ? 'income' : 'expense';
const category = isProfit ? 'Trading Profit' : 'Trading Loss';
const product = `${symbol} (${action})`;

const duplicateKey = `${whatsappNumber}|${date}|trade|${tradeId}|${absAmount}`;

return [{
  json: {
    trade_id: tradeId,
    symbol,
    action,
    broker,
    pnl: rawPnl,
    is_profit: isProfit,
    whatsapp_number: whatsappNumber,
    Month: month,
    Date: date,
    Type: type,
    Category: category,
    Vendor: broker,
    Product: product,
    Amount: absAmount,
    Currency: currency,
    currency_symbol: currencySymbol,
    notes,
    duplicate_key: duplicateKey,
    source: 'trading_bot',
    raw_data: JSON.stringify({ symbol, action, pnl: rawPnl, broker, date })
  }
}];

